SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_log,page_revisions,user_sites,users,media,menu_items,blocks,pages,themes,sites,redirects;
CREATE TABLE sites (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,host VARCHAR(190) NOT NULL UNIQUE,slug VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(190) NOT NULL,lang CHAR(2) NOT NULL DEFAULT 'sk',theme_id INT UNSIGNED NULL,home_page_id INT UNSIGNED NULL,is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE themes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,tokens JSON NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE pages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,parent_id INT UNSIGNED NULL,slug VARCHAR(150) NOT NULL,title VARCHAR(255) NOT NULL,template ENUM('home','vizitka','text','contact') NOT NULL DEFAULT 'text',meta_description VARCHAR(300) NULL,meta_keywords VARCHAR(300) NULL,og_title VARCHAR(200) NULL,og_description VARCHAR(300) NULL,og_image_id INT UNSIGNED NULL,status ENUM('draft','published') NOT NULL DEFAULT 'draft',position SMALLINT UNSIGNED NOT NULL DEFAULT 0,show_in_menu TINYINT(1) NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_page(site_id,parent_id,slug),KEY idx_pages_site_status(site_id,status),FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES pages(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE blocks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,page_id INT UNSIGNED NOT NULL,type ENUM('heading','richtext','image','links','contact','gallery') NOT NULL,sort_order SMALLINT NOT NULL DEFAULT 0,data JSON NOT NULL,aria_label VARCHAR(150) NULL,KEY idx_blocks_page_sort(page_id,sort_order),FOREIGN KEY(page_id) REFERENCES pages(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE menu_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,parent_id INT UNSIGNED NULL,label VARCHAR(100) NOT NULL,page_id INT UNSIGNED NULL,url VARCHAR(500) NULL,target ENUM('_self','_blank') NOT NULL DEFAULT '_self',aria_label VARCHAR(150) NULL,sort_order SMALLINT NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,KEY idx_menu_site_sort(site_id,sort_order),FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE media (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NULL,path VARCHAR(300) NOT NULL,alt_text VARCHAR(300) NOT NULL,is_decorative TINYINT(1) NOT NULL DEFAULT 0,mime VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,totp_secret VARCHAR(255) NULL,role ENUM('superadmin','editor') NOT NULL DEFAULT 'editor',failed_login_count INT UNSIGNED NOT NULL DEFAULT 0,locked_until DATETIME NULL,last_login_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE user_sites (user_id INT UNSIGNED NOT NULL,site_id INT UNSIGNED NOT NULL,PRIMARY KEY(user_id,site_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,action VARCHAR(60) NOT NULL,entity VARCHAR(60) NOT NULL,entity_id INT UNSIGNED NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE page_revisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,page_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NULL,snapshot JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(page_id) REFERENCES pages(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE redirects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,from_path VARCHAR(500) NOT NULL,to_path VARCHAR(500) NOT NULL,status_code SMALLINT UNSIGNED NOT NULL DEFAULT 301,UNIQUE KEY uq_redirect(site_id,from_path),FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET FOREIGN_KEY_CHECKS=1;
